function validate(schema, obj) {
  for (const [key, type] of Object.entries(schema)) {
    if (typeof obj[key] !== type) {
      throw new TypeError(`${key} must be ${type}, got ${typeof obj[key]}`);
    }
  }
  return true;
}

validate({ name: 'string', age: 'number' }, { name: 'Alice', age: 30 });

